import { client, schedules } from "@trigger.dev/sdk";

// Initialize the client
client.init({
  id: "scheduled-sync-scheduled_sync__XZ6Pex2",
  apiKey: process.env.TRIGGER_API_KEY,
});

// Define the Todo type
interface Todo {
  userId: number;
  id: number;
  title: string;
  completed: boolean;
}

// Create a scheduled task that runs every minute
schedules.task({
  id: "scheduled-sync-scheduled_sync__XZ6Pex2",
  run: async (payload) => {
    // Fetch todos from the mock API
    const response = await fetch("https://jsonplaceholder.typicode.com/todos");
    const todos: Todo[] = await response.json();

    // Log the number of items processed
    console.log(`Processed ${todos.length} todos`);

    return {
      count: todos.length,
      timestamp: new Date().toISOString(),
    };
  },
});

